package com.worklyn.modules.leave.service;
import com.worklyn.modules.attendance.service.AttendanceService;import com.worklyn.modules.integration.*;import com.worklyn.modules.leave.dto.*;import com.worklyn.modules.leave.model.*;import com.worklyn.modules.leave.repository.*;
import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Service public class LeaveService {
 private final LeaveRequestRepository requests;private final LeaveBalanceRepository balances;private final EmployeeDirectory employees;private final AttendanceService attendance;private final WorkflowRecoveryPort rewind;
 public LeaveService(LeaveRequestRepository r,LeaveBalanceRepository b,EmployeeDirectory e,AttendanceService a,WorkflowRecoveryPort w){requests=r;balances=b;employees=e;attendance=a;rewind=w;}
 public LeaveBalance getOrCreateBalance(String employeeId,int year){return balances.findByEmployeeIdAndYear(employeeId,year).orElseGet(()->{LeaveBalance b=new LeaveBalance();b.setEmployeeId(employeeId);b.setYear(year);return balances.save(b);});}
 public LeaveBalanceResponse balance(String employeeId){return LeaveBalanceResponse.from(getOrCreateBalance(employeeId,LocalDate.now().getYear()));}
 public List<LeaveResponse> myRequests(String employeeId){return requests.findByEmployeeIdOrderByCreatedAtDesc(employeeId).stream().map(LeaveResponse::from).toList();}
 public LeaveResponse apply(ApplyLeaveRequest req,String employeeId){if(employeeId==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No employee profile is linked to the authenticated user");LocalDate today=LocalDate.now();if(req.startDate().isBefore(today)||req.startDate().isAfter(req.endDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Leave dates must be valid and cannot start in the past");if(req.leaveType()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Leave type is required");
  boolean overlap=!requests.findByEmployeeIdAndStatusInAndStartDateLessThanEqualAndEndDateGreaterThanEqual(employeeId,List.of(LeaveStatus.PENDING,LeaveStatus.APPROVED),req.endDate(),req.startDate()).isEmpty();if(overlap)throw new ResponseStatusException(HttpStatus.CONFLICT,"An overlapping pending or approved leave request exists");int days=businessDays(req.startDate(),req.endDate());if(days<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Leave range contains no business days");LeaveBalance bal=getOrCreateBalance(employeeId,req.startDate().getYear());if(req.leaveType()!=LeaveType.UNPAID&&bal.available(req.leaveType())<days)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient leave balance: requested "+days+", available "+bal.available(req.leaveType()));if(req.leaveType()==LeaveType.MATERNITY||req.leaveType()==LeaveType.PATERNITY)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maternity/paternity balance policy must be configured by HR before use");LeaveRequest r=new LeaveRequest();r.setEmployeeId(employeeId);r.setLeaveType(req.leaveType());r.setStartDate(req.startDate());r.setEndDate(req.endDate());r.setTotalDays(days);r.setReason(req.reason().trim());r.setStatus(LeaveStatus.PENDING);r.setCreatedAt(Instant.now());return LeaveResponse.from(requests.save(r));}
 public LeaveResponse approve(String id,ActorContext actor,String remarks,String key){if(!actor.canApproveLeaves())throw new org.springframework.security.access.AccessDeniedException("Only HR, ADMIN, or MANAGER can approve leave");LeaveRequest r=find(id);if(r.getStatus()!=LeaveStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending leave can be approved");EmployeeSnapshot employee=employees.findById(r.getEmployeeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee profile not found"));if(!actor.isHrOrAdmin()&&!employees.canApprove(actor.userId(),employee))throw new org.springframework.security.access.AccessDeniedException("Manager is not authorized to approve this employee's leave");LeaveBalance b=getOrCreateBalance(r.getEmployeeId(),r.getStartDate().getYear());if(r.getLeaveType()!=LeaveType.UNPAID&&b.available(r.getLeaveType())<r.getTotalDays())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient leave balance at approval time");if(r.getLeaveType()!=LeaveType.UNPAID)b.deduct(r.getLeaveType(),r.getTotalDays());balances.save(b);r.setStatus(LeaveStatus.APPROVED);r.setApproverId(actor.userId());r.setDecisionRemarks(remarks);r.setDecisionDate(Instant.now());String workflow=rewind.registerLeaveApproval(id,r.getEmployeeId(),key,Map.of("startDate",r.getStartDate().toString(),"endDate",r.getEndDate().toString(),"days",r.getTotalDays()));r.setWorkflowId(workflow);LeaveRequest saved=requests.save(r);attendance.markOnLeave(r.getEmployeeId(),r.getStartDate(),r.getEndDate());return LeaveResponse.from(saved);}
 public LeaveResponse reject(String id,ActorContext actor,String remarks){if(!actor.canApproveLeaves())throw new org.springframework.security.access.AccessDeniedException("Only HR, ADMIN, or MANAGER can reject leave");if(remarks==null||remarks.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Remarks are required when rejecting leave");LeaveRequest r=find(id);if(r.getStatus()!=LeaveStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending leave can be rejected");EmployeeSnapshot employee=employees.findById(r.getEmployeeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee profile not found"));if(!actor.isHrOrAdmin()&&!employees.canApprove(actor.userId(),employee))throw new org.springframework.security.access.AccessDeniedException("Manager is not authorized to reject this employee's leave");r.setStatus(LeaveStatus.REJECTED);r.setApproverId(actor.userId());r.setDecisionRemarks(remarks.trim());r.setDecisionDate(Instant.now());return LeaveResponse.from(requests.save(r));}
 public LeaveResponse cancel(String id,ActorContext actor){LeaveRequest r=find(id);boolean owner=Objects.equals(r.getEmployeeId(),actor.employeeId());if(r.getStatus()==LeaveStatus.PENDING){if(!owner&&!actor.isHrOrAdmin())throw new org.springframework.security.access.AccessDeniedException("Only the applicant or HR can cancel pending leave");r.setStatus(LeaveStatus.CANCELLED);}else if(r.getStatus()==LeaveStatus.APPROVED){if(!actor.isHrOrAdmin())throw new org.springframework.security.access.AccessDeniedException("Only HR/ADMIN can cancel approved leave");if(r.getLeaveType()!=LeaveType.UNPAID){LeaveBalance b=getOrCreateBalance(r.getEmployeeId(),r.getStartDate().getYear());b.credit(r.getLeaveType(),r.getTotalDays());balances.save(b);}attendance.removeOnLeave(r.getEmployeeId(),r.getStartDate(),r.getEndDate());r.setStatus(LeaveStatus.CANCELLED);}else throw new ResponseStatusException(HttpStatus.CONFLICT,"Rejected or cancelled leave cannot be cancelled");r.setApproverId(actor.userId());r.setDecisionDate(Instant.now());return LeaveResponse.from(requests.save(r));}
 public List<LeaveRequest> approvedForPeriod(String employeeId,LocalDate start,LocalDate end){return requests.findByEmployeeIdAndStatusAndStartDateLessThanEqualAndEndDateGreaterThanEqual(employeeId,LeaveStatus.APPROVED,end,start);}
 private LeaveRequest find(String id){return requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found"));}
 private int businessDays(LocalDate start,LocalDate end){int n=0;for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1))if(d.getDayOfWeek().getValue()<6)n++;return n;}
}
